action.implementation:
async () => {
    setPwError(null);
    setNewPwError(null);
    setConfirmError(null);
    if (!currentPw) {
      setPwError(t("catalog.err.required"));
      return;
    }
    if (newPw.length < 12) {
      setNewPwError(t("reset.tooShort"));
      return;
    }
    if (newPw.length > 128) {
      setNewPwError(t("reset.tooLong"));
      return;
    }
    if (newPw !== confirmPw) {
      setConfirmError(t("reset.mismatch"));
      return;
    }
    setSaving(true);
    await mockLatency(600);
    if (currentPw !== "demo1234") {
      setPwError(t("profile.password.wrongCurrent"));
      setSaving(false);
      return;
    }
    setCurrentPw("");
    setNewPw("");
    setConfirmPw("");
    setSaving(false);
    toast("success", t("profile.password.success"));
  }

async () => {
    if (slug && !slugValid) {
      setSlugError(t("settings.identity.slugInvalid"));
      return;
    }
    setSaving(true);
    await mockLatency(400);
    persistStorefront({ slug: slug || null, displayName: { ...displayNames } });
    setSaving(false);
    flashSaved("identity");
    toast("success", t("settings.saved"));
  }

async () => {
    const e = validateProduct(value, taken, t);
    setErrors(e);
    if (Object.keys(e).length > 0) return;
    setSubmitting(true);
    setSubmitError(false);
    try {
      await mockLatency(600);
      const product: Product = {
        id: `p_${Math.random().toString(36).slice(2, 9)}`,
        merchantId: user!.id,
        internalName: value.internalName.trim(),
        title: { "pt-BR": value.title["pt-BR"].trim(), en: value.title.en.trim() },
        description: { "pt-BR": value.description["pt-BR"].trim(), en: value.description.en.trim() },
        price: { amount: parsePrice(value.price), currency: "BRL" },
        categoryId: value.categoryId || null,
        imageUrl: value.imageUrl,
        state: value.state,
        createdAt: new Date().toISOString(),
      };
      productFixtures.push(product);
      toast("success", t("catalog.create.success"));
      navigate(`/catalog/products/${product.id}`);
    } catch {
      setSubmitError(true);
    } finally {
      setSubmitting(false);
    }
  }

