action.implementation:
async () => {
    if (!newPt.trim() || !newEn.trim()) {
      setNewError(t("catalog.err.required"));
      return;
    }
    if (duplicateName(newPt, newEn)) {
      setNewError(t("catalog.categories.duplicate"));
      return;
    }
    setAdding(true);
    setNewError(null);
    await mockLatency(500);
    const cat: Category = {
      id: `c_${Math.random().toString(36).slice(2, 9)}`,
      merchantId: user!.id,
      name: { "pt-BR": newPt.trim(), en: newEn.trim() },
      state: "active",
      createdAt: new Date().toISOString(),
    };
    categoryFixtures.push(cat);
    setCats((cs) => [...cs, cat]);
    setNewPt("");
    setNewEn("");
    setAdding(false);
    toast("success", t("catalog.categories.addSuccess"));
  }

async () => {
    if (!value) return;
    const e = validateProduct(value, existingNames, t);
    setErrors(e);
    if (Object.keys(e).length > 0) return;
    setSaving(true);
    setConflict(false);
    try {
      await mockLatency(600);
      // Simulated concurrent-edit conflict: ~25% of saves fail once with a safe banner.
      if (Math.random() < 0.25) {
        setConflict(true);
        return;
      }
      persist({
        internalName: value.internalName.trim(),
        title: { "pt-BR": value.title["pt-BR"].trim(), en: value.title.en.trim() },
        description: { "pt-BR": value.description["pt-BR"].trim(), en: value.description.en.trim() },
        price: { amount: parsePrice(value.price), currency: "BRL" },
        categoryId: value.categoryId || null,
        imageUrl: value.imageUrl,
        state: value.state,
      });
      setBaseline(JSON.stringify(value));
      toast("success", t("catalog.detail.saveSuccess"));
    } catch {
      toast("error", t("common.requestError"), { onRetry: save });
    } finally {
      setSaving(false);
    }
  }

