    const fx = categoryFixtures.find((c) => c.id === deactTarget.id);
    if (fx) fx.state = "inactive";
    setCats((cs) => cs.map((c) => (c.id === deactTarget.id ? { ...c, state: "inactive" } : c)));
    setActing(false);
    setDeactTarget(null);
