deactivate = async () => {
    if (!deactTarget) return;
    const count = refCount(deactTarget.id);
    if (count > 0) {
      const ok = cats.some((x) => x.state === "active" && x.id !== deactTarget.id);
      if (!ok || !replacement) return; // blocked — no replacement available
    }
    setActing(true);
    await mockLatency(500);
    if (count > 0) {
      productFixtures.forEach((p) => {
        if (p.categoryId === deactTarget.id) p.categoryId = replacement;
      });
      setProducts((ps) => ps.map((p) => (p.categoryId === deactTarget.id ? { ...p, categoryId: replacement } : p)));
    }
    const fx = categoryFixtures.find((c) => c.id === deactTarget.id);
    if (fx) fx.state = "inactive";
    setCats((cs) => cs.map((c) => (c.id === deactTarget.id ? { ...c, state: "inactive" } : c)));
    setActing(false);
    setDeactTarget(null);
    toast("success", t("catalog.categories.deactivateSuccess"));
  }

confirmToggle = async () => {
    if (!pending) return;
    await mockLatency(400);
    pending.status = pending.status === "active" ? "inactive" : "active";
    setItems([...config.exchangeCurrencies]);
    setPending(null);
    banner.flash();
  }

useCallback(async () => {
    if (!link || submitting) return;
    const errs = validate(form, link.policy);
    setErrors(errs);
    const keys = Object.keys(errs) as (keyof BuyerForm)[];
    if (keys.length > 0) {
      const el = document.querySelector<HTMLElement>(`[data-field="${keys[0]}"]`);
      firstErrorRef.current = el;
      el?.scrollIntoView({ behavior: "smooth", block: "center" });
      return;
    }
    setSubmitting(true);
    setSubmitError(false);
    try {
      await mockLatency(900);
      if (SUBMIT_FAILS_ONCE.has(link.identifier) && !submitFailedOnce.current) {
        submitFailedOnce.current = true;
        throw new Error("simulated submission failure");
      }
      pollStep.current = 0;
      hiccupConsumed.current = false;
      setAttempt({ ref: `pay_${Math.random().toString(36).slice(2, 10)}${link.identifier}`, qrPayload: null, state: "created", pollFailed: false });
    } catch {
      setSubmitError(true);
    } finally {
      setSubmitting(false);
    }
  }, [link, submitting, form])

