                    type={show ? "text" : "password"}
                    autoComplete="new-password"
                    value={confirm}
                    onChange={(e) => setConfirm(e.target.value)}
                    onBlur={() => {
                      if (confirm && confirm !== password) setErrors((er) => ({ ...er, confirm: t("reset.mismatch") }));
