      setData(d);
      setError(false);
      setStale(false);
    } catch {
      // Keep previous data as stale if present; otherwise full error strip.
      setError(true);
      setStale((prev) => prev || data !== null);
    } finally {
      setLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id, period, simulateError])

